phoenix_power_comparison.probe_source:
extends SceneTree
const Phoenix := preload("res://workshop/creator/phoenix/physics.gd")
const Packages := preload("res://workshop/creator/packages.gd")
const Propulsion := preload("res://physics/propulsion.gd")
const AircraftData := preload("res://physics/aircraft_data.gd")
func _initialize() -> void:
	var block := {format = Phoenix.FORMAT, airfoil = "Synthetic", section = {
		slope = 6.0, cl_zero = 0.0, cl_at_incidence = 0.0, cl_max = 1.3, cl_min = -1.3,
		cd_min = 0.02, cl_min_drag = 0.0, stall_width_deg = 4.0},
		wing_lift_slope = Phoenix.helmbold(5.0), aspect_ratio = 5.0, body_drag_ratio = 0.03,
		mass_kg = 10.0, propeller = {diameter_m = 0.20, pitch_m = 0.15, max_rpm = 8000.0, blades = 6}}
	for count: int in [1, 2, 4]:
		block.propeller.count = count
		var ids := Phoenix.derive(block, "conventional-trainer-estimated-v1", "electric-3s-1250kv-9x6-estimated-v1", 1.0)
		if ids.is_empty():
			printerr("derive refused count=",count)
			quit(1); return
		var power: Dictionary = Packages.power(ids.power).value
		var thrust: Dictionary = Packages.static_thrust(power, 1.0)
		var record: Dictionary = Packages.propulsion_block(power, "prop", 1.0, PackedFloat64Array([0.0, 0.0, 0.0]), PackedFloat64Array([0.0, 0.0]))
		record.erase("id")
		var errors: PackedStringArray = []
		var loaded: Dictionary = AircraftData._electric_propulsion(errors, record)
		var ct: float = power.propeller.ct_table.value[0][1]
		var cp: float = power.propeller.cp_table.value[0][1]
		var d: float = power.propeller.diameter.value
		var n := 8000.0 / 60.0
		var rho := 1.225
		var force := rho*n*n*pow(d,4)*ct
		var watts := rho*n*n*n*pow(d,5)*cp
		var disk := PI*d*d/4.0
		var physical_fm := pow(force,1.5)/sqrt(2.0*rho*disk)/watts
		var values := {count=count,diameter=d,ct=ct,cp=cp,static_thrust=thrust.get("thrust_n", NAN),
			rpm=thrust.get("rpm", NAN),physical_fm=physical_fm,motor_kv=power.motor.kv_rpm_per_volt.value,
			inertia=power.propeller.rotating_inertia.value,load_ok=not loaded.is_empty() and errors.is_empty(),errors=Array(errors)}
		print("BASELINE ",JSON.stringify(values))
	print("PHOENIX_COMPARISON_COMPLETE")
	quit()
